mapper.delete:
        DELETE FROM BOK_BALANCE A
        WHERE EXISTS(
            SELECT 1  
            FROM BOK_BATCH_TASK_TODO B
		    WHERE  
	      		B.BOOKSET_ID =  A.BOOKSET_ID

	      		AND B.SEQ_NO = #{seqNo}
				AND B.BOOKSET_DATE = #{BOOKSET_DATE}
	            AND B.BOOK_DATE = #{BOOK_DATE}
	            AND B.HAPPEN_DATE = #{HAPPEN_DATE}
                AND B.TASK_ID = #{taskId}
                AND B.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET}
        )
        AND A.BALANCE_DATE >= #{BOOK_DATE}

mapper.select:
        SELECT 
            btt.BOOKSET_ID as booksetId,
            btt.HAPPEN_DATE as hanppenDate,
            btt.BOOK_DATE as bookDate,
            btt.BOOKSET_DATE as booksetDate,
            bb.STANDARD_CCY as standardCcy
        FROM BOK_BATCH_TASK_TODO btt
        LEFT JOIN BOK_BOOKSET bb
            ON bb.BOOKSET_ID = btt.BOOKSET_ID
        LEFT JOIN BOK_BOOKSET_DATE bbd
            ON bbd.BOOKSET_ID = btt.BOOKSET_ID   
        WHERE
            btt.SEQ_NO = #{seqNo}
			AND btt.BOOKSET_DATE = #{BOOKSET_DATE}
            AND btt.BOOK_DATE = #{BOOK_DATE}
            AND btt.HAPPEN_DATE = #{HAPPEN_DATE}
            AND btt.TASK_ID = #{taskId}
            AND btt.IS_SUB_BOOKSET = #{IS_SUB_BOOKSET}
